import { useCallback, useEffect, useRef, useState } from "react";
import type { StepStatus, StreamWarning } from "../types";

interface UseChatStreamOptions {
  sessionId?: string | null;
  onComplete?: () => Promise<void> | void;
}

interface StreamingTurn {
  user: string;
  assistant: string;
}

interface UseChatStreamResult {
  sendMessage: (message: string) => Promise<void>;
  isStreaming: boolean;
  streamingTurn: StreamingTurn | null;
  stepStatuses: StepStatus[];
  warning: StreamWarning | null;
  error: string | null;
}

export function useChatStream(
  options: UseChatStreamOptions
): UseChatStreamResult {
  const { sessionId, onComplete } = options;
  const [isStreaming, setIsStreaming] = useState(false);
  const [streamingTurn, setStreamingTurn] = useState<StreamingTurn | null>(null);
  const [stepMap, setStepMap] = useState<Record<string, StepStatus>>({});
  const [warning, setWarning] = useState<StreamWarning | null>(null);
  const [error, setError] = useState<string | null>(null);
  const abortRef = useRef<AbortController | null>(null);

  useEffect(() => {
    return () => {
      abortRef.current?.abort();
    };
  }, []);

  const handleBlock = useCallback(
    (block: string) => {
    let event: string | null = null;
    let dataStr = "";
    for (const line of block.split("\n")) {
      if (line.startsWith("event:")) {
        event = line.replace("event:", "").trim();
      } else if (line.startsWith("data:")) {
        dataStr += line.replace("data:", "").trim();
      }
    }

    if (!event) {
      return;
    }

    let data: any = {};
    if (dataStr) {
      try {
        data = JSON.parse(dataStr);
      } catch {
        data = { message: dataStr };
      }
    }

    switch (event) {
      case "step":
        if (data.id) {
          setStepMap((prev) => ({
            ...prev,
            [data.id]: { id: data.id, status: data.status ?? "complete", ...data }
          }));
        }
        break;
      case "chunk":
        if (typeof data.content === "string") {
          setStreamingTurn((prev) =>
            prev ? { ...prev, assistant: prev.assistant + data.content } : prev
          );
        }
        break;
      case "warning":
        setWarning({ code: data.code, message: data.message ?? "Warning" });
        break;
      case "error":
        setError(data.message ?? "Pipeline error");
        break;
      case "done":
        setStreamingTurn(null);
        setStepMap({});
        if (onComplete) {
          Promise.resolve(onComplete()).catch((err) =>
            console.error("Refresh failed", err)
          );
        }
        break;
      default:
        break;
    }
  },
  [onComplete]
  );

  const sendMessage = useCallback(
    async (message: string) => {
      if (!sessionId) {
        setError("Session not ready yet.");
        return;
      }

      const trimmed = message.trim();
      if (!trimmed) {
        return;
      }

      abortRef.current?.abort();
      const controller = new AbortController();
      abortRef.current = controller;

      setIsStreaming(true);
      setStreamingTurn({ user: trimmed, assistant: "" });
      setStepMap({});
      setWarning(null);
      setError(null);

      try {
        const response = await fetch("/api/chat", {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({ message: trimmed, session_id: sessionId }),
          signal: controller.signal
        });

        if (!response.ok || !response.body) {
          const payload = await response.json().catch(() => ({}));
          throw new Error(
            payload?.error?.message || "Chat request failed. Check backend logs."
          );
        }

        const reader = response.body.getReader();
        const decoder = new TextDecoder("utf-8");
        let buffer = "";

        while (true) {
          const { value, done } = await reader.read();
          if (done) {
            break;
          }
          buffer += decoder.decode(value, { stream: true });
          let boundary = buffer.indexOf("\n\n");
          while (boundary !== -1) {
            const block = buffer.slice(0, boundary).trim();
            buffer = buffer.slice(boundary + 2);
            if (block) {
              handleBlock(block);
            }
            boundary = buffer.indexOf("\n\n");
          }
        }
      } catch (err) {
        if (controller.signal.aborted) {
          setWarning({ code: "aborted", message: "Stream cancelled." });
        } else {
          setError(err instanceof Error ? err.message : "Unknown error");
        }
      } finally {
        setIsStreaming(false);
        abortRef.current = null;
      }
    },
    [handleBlock, sessionId]
  );

  return {
    sendMessage,
    isStreaming,
    streamingTurn,
    stepStatuses: Object.values(stepMap),
    warning,
    error
  };
}

