import { useCallback, useEffect, useState } from "react";
import { Carousel } from "./components/Carousel";
import { InputBox } from "./components/InputBox";
import { useChatStream } from "./hooks/useChatStream";
import type { SessionHistory, Turn } from "./types";

interface HealthState {
  status: string;
  details?: string;
}

export default function App() {
  const [sessionId, setSessionId] = useState<string | null>(null);
  const [turns, setTurns] = useState<Turn[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [banner, setBanner] = useState<string | null>(null);
  const [health, setHealth] = useState<HealthState | null>(null);

  const fetchHistory = useCallback(
    async (id?: string) => {
      const targetId = id ?? sessionId;
      if (!targetId) return;
      const response = await fetch(`/api/sessions/${targetId}`);
      if (!response.ok) {
        const errorBody = await response.json().catch(() => ({}));
        throw new Error(errorBody?.error?.message ?? "Failed to load session.");
      }
      const data = (await response.json()) as SessionHistory;
      setTurns(data.turns);
    },
    [sessionId]
  );

  const createSession = useCallback(async () => {
    const response = await fetch("/api/sessions", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ metadata: { source: "turnstile-ui" } })
    });
    if (!response.ok) {
      const errorBody = await response.json().catch(() => ({}));
      throw new Error(errorBody?.error?.message ?? "Unable to create session.");
    }
    const data = await response.json();
    setSessionId(data.session_id);
    return data.session_id as string;
  }, []);

  useEffect(() => {
    let cancelled = false;
    async function bootstrap() {
      try {
        setIsLoading(true);
        const newSessionId = await createSession();
        if (!cancelled) {
          await fetchHistory(newSessionId);
        }
      } catch (err) {
        if (!cancelled) {
          setBanner(err instanceof Error ? err.message : "Failed to start session.");
        }
      } finally {
        if (!cancelled) {
          setIsLoading(false);
        }
      }
    }
    bootstrap();
    return () => {
      cancelled = true;
    };
  }, [createSession, fetchHistory]);

  useEffect(() => {
    fetch("/api/health")
      .then((res) => res.json())
      .then((data) => setHealth({ status: data.status ?? "unknown", details: data.mode ?? data.sak_status }))
      .catch(() => setHealth({ status: "unknown" }));
  }, []);

  const { sendMessage, streamingTurn, isStreaming, stepStatuses, warning, error } = useChatStream({
    sessionId,
    onComplete: () => fetchHistory()
  });

  return (
    <div className="app-shell">
      <header className="app-header">
        <div>
          <h1>Turnstile</h1>
          <p>Turn-centric interface for whitepaper chat.</p>
        </div>
        <div className="status-pill" data-status={health?.status ?? "unknown"}>
          Stack: {health?.status ?? "unknown"}
          {health?.details ? <span> ({health.details})</span> : null}
        </div>
      </header>

      {banner && <div className="banner banner--error">{banner}</div>}
      {warning && <div className="banner banner--warning">{warning.message}</div>}
      {error && <div className="banner banner--error">{error}</div>}

      <section className="step-status">
        {["session", "docs", "persona"].map((step) => {
          const info = stepStatuses.find((s) => s.id === step);
          const state = info?.status ?? "pending";
          return (
            <div key={step} className={`step-pill step-pill--${state}`}>
              <span className="step-pill__label">{step}</span>
              <span className="step-pill__state">{state}</span>
            </div>
          );
        })}
      </section>

      <main className="app-main">
        {isLoading ? (
          <div className="loading">Creating session…</div>
        ) : (
          <Carousel turns={turns} streamingTurn={streamingTurn} />
        )}
      </main>

      <footer className="app-footer">
        <InputBox disabled={isStreaming || !sessionId} onSubmit={sendMessage} />
        <p className="hint">
          {sessionId
            ? `Session ${sessionId} • ${turns.length} turn${turns.length === 1 ? "" : "s"}`
            : "Preparing session…"}
        </p>
      </footer>
    </div>
  );
}

