import cors from "cors";
import express from "express";
import { config } from "./config.js";
import { createOrchestratorHandlers } from "./orchestratorProxy.js";
import { createStubHandlers } from "./stub.js";

const app = express();

app.use(
  cors({
    origin: config.corsOrigin,
    methods: ["GET", "POST"],
    allowedHeaders: ["Content-Type"]
  })
);
app.use(express.json());

const handlers = config.stubMode
  ? createStubHandlers(config)
  : createOrchestratorHandlers(config);

app.get("/api/health", handlers.health);
app.post("/api/chat", handlers.chat);
app.post("/api/sessions", handlers.createSession);
app.get("/api/sessions/:id", handlers.getSession);

app.get("/", (_req, res) => {
  res.json({
    service: "turnstile-backend",
    stub_mode: config.stubMode,
    orchestrator_url: config.orchestratorUrl ?? null
  });
});

app.listen(config.port, () => {
  console.log(
    `Turnstile backend running on port ${config.port} (${config.stubMode ? "stub" : "proxy"} mode)`
  );
});

