import type { Request, Response } from "express";
import type { TurnstileConfig } from "./config.js";

type Handler = (req: Request, res: Response) => Promise<void> | void;

function buildUrl(base: string, path: string): string {
  if (base.endsWith("/")) {
    return `${base.slice(0, -1)}${path}`;
  }
  return `${base}${path}`;
}

async function proxyJson(
  req: Request,
  res: Response,
  targetUrl: string,
  init?: RequestInit
) {
  const controller = new AbortController();
  req.on("close", () => controller.abort());

  const upstream = await fetch(targetUrl, {
    ...init,
    headers: {
      "Content-Type": "application/json",
      ...(init?.headers ?? {})
    },
    signal: controller.signal
  });

  const text = await upstream.text();
  const contentType = upstream.headers.get("content-type");
  const payload =
    contentType && contentType.includes("application/json")
      ? JSON.parse(text || "{}")
      : text;

  res.status(upstream.status);
  if (typeof payload === "string") {
    res.type(contentType ?? "text/plain").send(payload);
  } else {
    res.json(payload);
  }
}

async function proxySse(
  req: Request,
  res: Response,
  targetUrl: string,
  body: string,
  extraHeaders?: Record<string, string>
) {
  const controller = new AbortController();
  req.on("close", () => controller.abort());

  const upstream = await fetch(targetUrl, {
    method: "POST",
    headers: {
      "Content-Type": "application/json",
      ...extraHeaders
    },
    body,
    signal: controller.signal
  });

  if (!upstream.ok) {
    const errorPayload = await upstream.text();
    res.status(upstream.status);
    res.type(upstream.headers.get("content-type") ?? "application/json");
    res.send(errorPayload || JSON.stringify({ error: { message: "Upstream error" } }));
    return;
  }

  res.status(200);
  res.setHeader("Content-Type", "text/event-stream");
  res.setHeader("Cache-Control", "no-cache");
  res.setHeader("Connection", "keep-alive");

  const reader = upstream.body?.getReader();

  if (!reader) {
    res.write(`event: error\ndata: ${JSON.stringify({
      code: "stream_unavailable",
      message: "No upstream stream"
    })}\n\n`);
    res.end();
    return;
  }

  const close = () => reader.cancel().catch(() => undefined);
  req.on("close", close);

  while (true) {
    const { done, value } = await reader.read();
    if (done) {
      break;
    }
    if (value) {
      res.write(Buffer.from(value));
    }
  }
  res.end();
}

export function createOrchestratorHandlers(
  cfg: TurnstileConfig
): Record<"chat" | "createSession" | "getSession" | "health", Handler> {
  // Chat requires Orchestrator
  if (!cfg.orchestratorUrl) {
    const missingOrchestrator: Handler = (_req, res) => {
      res.status(500).json({
        error: {
          code: "orchestrator_unconfigured",
          message: "ORCHESTRATOR_URL is not set."
        }
      });
    };
    return {
      chat: missingOrchestrator,
      createSession: missingOrchestrator,
      getSession: missingOrchestrator,
      health: (_req, res) => {
        res.json({
          status: "degraded",
          orchestrator: "missing"
        });
      }
    };
  }

  const orchestrator = cfg.orchestratorUrl;
  // Session operations go through SAK Router -> Session Manager
  const sakRouter = cfg.sakRouterUrl ?? "http://localhost:3005";

  const chat: Handler = async (req, res) => {
    const payload = JSON.stringify(req.body ?? {});
    const path = `/orchestrate/${cfg.pipelineName}`;
    await proxySse(req, res, buildUrl(orchestrator, path), payload);
  };

  // Session creation: POST /sessions -> SAK Router -> Session Manager
  const createSession: Handler = (req, res) =>
    proxyJson(req, res, buildUrl(sakRouter, "/sessions"), {
      method: "POST",
      body: JSON.stringify(req.body ?? {})
    });

  // Session retrieval: GET /sessions/{id}/history -> SAK Router -> Session Manager
  const getSession: Handler = (req, res) =>
    proxyJson(
      req,
      res,
      buildUrl(sakRouter, `/sessions/${req.params.id}/history`),
      { method: "GET" }
    );

  // Health check goes to Orchestrator (which checks SAK status)
  const health: Handler = (req, res) =>
    proxyJson(req, res, buildUrl(orchestrator, "/health"), { method: "GET" });

  return { chat, createSession, getSession, health };
}

