export interface TurnstileConfig {
  port: number;
  corsOrigin: string | undefined;
  orchestratorUrl: string | undefined;
  sakRouterUrl: string | undefined;
  pipelineName: string;
  stubMode: boolean;
  stubLatencyMs: number;
}

function parseBoolean(value: string | undefined, fallback = false): boolean {
  if (value === undefined) {
    return fallback;
  }
  return ["1", "true", "TRUE", "yes", "YES"].includes(value.trim());
}

function parseNumber(value: string | undefined, fallback: number): number {
  const parsed = Number(value);
  return Number.isFinite(parsed) ? parsed : fallback;
}

export function loadConfig(env = process.env): TurnstileConfig {
  return {
    port: parseNumber(env.TURNSTILE_PORT ?? env.PORT, 3001),
    corsOrigin: env.CORS_ORIGIN ?? "http://localhost:5173",
    orchestratorUrl: env.ORCHESTRATOR_URL,
    sakRouterUrl: env.SAK_ROUTER_URL ?? "http://localhost:3005",
    pipelineName: env.PIPELINE_NAME ?? "whitepaper-chat",
    stubMode: parseBoolean(env.STUB_MODE, true),
    stubLatencyMs: parseNumber(env.STUB_LATENCY_MS, 250)
  };
}

export const config = loadConfig();
